// SettingsBackTo says "Back to {name}"
// in the language the app shows under cx.
func SettingsBackTo(cx *core.Scope, name string) string { return For(cx).SettingsBackTo(name) }

// SettingsBackTo is the package's SettingsBackTo in the language of msgs.
func (msgs Messages) SettingsBackTo(name string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.SettingsBackTo(name))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].SettingsBackTo; f != nil {
			return f(name)
		}
		switch lang {
		case "", "en":
			return "Back to " + msgs.arg(name)
		case "zh-Hans":
			return "返回" + name
		case "zh-Hant":
			return "返回" + name
		}
	}
}

