func (msgs Messages) AgentswitcherCountOne(count int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.AgentswitcherCountOne(count))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].AgentswitcherCountOne; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			return msgs.arg(i18n.FormatNumber("en", float64(count))) + " agent"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + " 个 Agent"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(count)) + " 個 Agent"
		}
	}
}

