// SidebarWorktreeBranchInUse says "Branch “{branch}” is already checked out at {path}."
// in the language the app shows under cx.
func SidebarWorktreeBranchInUse(cx *core.Scope, branch string, path string) string {
	return For(cx).SidebarWorktreeBranchInUse(branch, path)
}

// SidebarWorktreeBranchInUse is the package's SidebarWorktreeBranchInUse in the language of msgs.
func (msgs Messages) SidebarWorktreeBranchInUse(branch string, path string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.SidebarWorktreeBranchInUse(branch, path))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].SidebarWorktreeBranchInUse; f != nil {
			return f(branch, path)
		}
		switch lang {
		case "", "en":
			return "Branch “" + msgs.arg(branch) + "” is already checked out at " + msgs.arg(path) + "."
		case "zh-Hans":
			return "分支「" + branch + "」已在 " + path + " 检出。"
		case "zh-Hant":
			return "分支「" + branch + "」已在 " + path + " 簽出。"
		}
	}
}

// SidebarWorktreeBranchMissing says "Branch “{branch}” still belongs to a worktree whose folder is gone ({path}). Run git worktree prune to clear it."
// in the language the app shows under cx.
func SidebarWorktreeBranchMissing(cx *core.Scope, branch string, path string) string {
	return For(cx).SidebarWorktreeBranchMissing(branch, path)
}

// SidebarWorktreeBranchMissing is the package's SidebarWorktreeBranchMissing in the language of msgs.
func (msgs Messages) SidebarWorktreeBranchMissing(branch string, path string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.SidebarWorktreeBranchMissing(branch, path))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].SidebarWorktreeBranchMissing; f != nil {
			return f(branch, path)
		}
		switch lang {
		case "", "en":
			return "Branch “" + msgs.arg(branch) + "” still belongs to a worktree whose folder is gone (" + msgs.arg(path) + "). Run git worktree prune to clear it."
		case "zh-Hans":
			return "分支「" + branch + "」仍属于一个文件夹已不存在的 worktree（" + path + "）。运行 git worktree prune 可清除它。"
		case "zh-Hant":
			return "分支「" + branch + "」仍屬於一個資料夾已不存在的 worktree（" + path + "）。執行 git worktree prune 即可清除。"
		}
	}
}

