// McpProjectNotListed says "This project's servers are not listed: {reason}"
// in the language the app shows under cx.
func McpProjectNotListed(cx *core.Scope, reason string) string {
	return For(cx).McpProjectNotListed(reason)
}

// McpProjectNotListed is the package's McpProjectNotListed in the language of msgs.
func (msgs Messages) McpProjectNotListed(reason string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.McpProjectNotListed(reason))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].McpProjectNotListed; f != nil {
			return f(reason)
		}
		switch lang {
		case "", "en":
			return "This project's servers are not listed: " + msgs.arg(reason)
		case "zh-Hans":
			return "未列出此项目的服务器：" + reason
		case "zh-Hant":
			return "未列出此專案的伺服器：" + reason
		}
	}
}

