	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.McpServerCount(enabled, total))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].McpServerCount; f != nil {
			return f(enabled, total)
		}
		switch lang {
		case "", "en":
			return msgs.arg(i18n.FormatNumber("en", float64(enabled))) + " of " + msgs.arg(i18n.FormatNumber("en", float64(total))) + " servers turned on"
		case "zh-Hans":
			return "已开启 " + i18n.FormatNumber("zh-Hans", float64(enabled)) + "/" + i18n.FormatNumber("zh-Hans", float64(total)) + " 个服务器"
		case "zh-Hant":
			return "已開啟 " + i18n.FormatNumber("zh-Hant", float64(enabled)) + "/" + i18n.FormatNumber("zh-Hant", float64(total)) + " 個伺服器"
		}
	}
