// McpTestSummaryConnected says "{count} tool(s) listed in {seconds} s, tested at {time}."
// in the language the app shows under cx.
func McpTestSummaryConnected(cx *core.Scope, count int, seconds int, time_ string) string {
	return For(cx).McpTestSummaryConnected(count, seconds, time_)
}

// McpTestSummaryConnected is the package's McpTestSummaryConnected in the language of msgs.
func (msgs Messages) McpTestSummaryConnected(count int, seconds int, time_ string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.McpTestSummaryConnected(count, seconds, time_))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].McpTestSummaryConnected; f != nil {
			return f(count, seconds, time_)
		}
		switch lang {
		case "", "en":
			return msgs.arg(i18n.FormatNumber("en", float64(count))) + " tool(s) listed in " + msgs.arg(i18n.FormatNumber("en", float64(seconds))) + " s, tested at " + msgs.arg(time_) + "."
		case "zh-Hans":
			return "列出了 " + i18n.FormatNumber("zh-Hans", float64(count)) + " 个工具，用时 " + i18n.FormatNumber("zh-Hans", float64(seconds)) + " 秒，测试于 " + time_ + "。"
		case "zh-Hant":
			return "列出了 " + i18n.FormatNumber("zh-Hant", float64(count)) + " 個工具，耗時 " + i18n.FormatNumber("zh-Hant", float64(seconds)) + " 秒，測試於 " + time_ + "。"
		}
	}
}

