// I18nResourceCount says "{count} {label}"
// in the language the app shows under cx.
func I18nResourceCount(cx *core.Scope, count int, label string) string {
	return For(cx).I18nResourceCount(count, label)
}

// I18nResourceCount is the package's I18nResourceCount in the language of msgs.
func (msgs Messages) I18nResourceCount(count int, label string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.I18nResourceCount(count, label))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].I18nResourceCount; f != nil {
			return f(count, label)
		}
		switch lang {
		case "", "en":
			return msgs.arg(i18n.FormatNumber("en", float64(count))) + " " + msgs.arg(label)
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + label
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(count)) + " 個" + label
		}
	}
}

