// I18nLargeMessageReveal says "Message content is very large ({size}). Click to view as plain text — markdown rendering is disabled to keep the page responsive."
// in the language the app shows under cx.
func I18nLargeMessageReveal(cx *core.Scope, size string) string {
	return For(cx).I18nLargeMessageReveal(size)
}

// I18nLargeMessageReveal is the package's I18nLargeMessageReveal in the language of msgs.
func (msgs Messages) I18nLargeMessageReveal(size string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.I18nLargeMessageReveal(size))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].I18nLargeMessageReveal; f != nil {
			return f(size)
		}
		switch lang {
		case "", "en":
			return "Message content is very large (" + msgs.arg(size) + "). Click to view as plain text — markdown rendering is disabled to keep the page responsive."
		case "zh-Hans":
			return "消息内容过大（" + size + "）。点击以纯文本查看 — 已禁用 markdown 渲染以避免页面卡顿。"
		case "zh-Hant":
			return "訊息內容過大（" + size + "）。點選即可用純文字查看；為保持頁面流暢，已停用 Markdown 轉譯。"
		}
	}
}

