func (msgs Messages) I18nFileContext(details string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.I18nFileContext(details))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].I18nFileContext; f != nil {
			return f(details)
		}
		switch lang {
		case "", "en":
			return "File context: " + msgs.arg(details)
		case "zh-Hans":
			return "文件上下文：" + details
		case "zh-Hant":
			return "檔案上下文：" + details
		}
	}
}

