// DiffUnchangedLines says "{count} unchanged lines"
// in the language the app shows under cx.
func DiffUnchangedLines(cx *core.Scope, count int) string { return For(cx).DiffUnchangedLines(count) }

// DiffUnchangedLines is the package's DiffUnchangedLines in the language of msgs.
func (msgs Messages) DiffUnchangedLines(count int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.DiffUnchangedLines(count))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].DiffUnchangedLines; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			return msgs.arg(i18n.FormatNumber("en", float64(count))) + " unchanged lines"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + " 行未改动"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(count)) + " 行未變更"
		}
	}
}

